class Solution:
    def next_greater(self, nums: list[int]) -> list[int]:
        res = [-1] * len(nums)
        stack = []

        for i, val in enumerate(nums):
            while stack and nums[stack[-1]] < val:
                idx = stack.pop()
                res[idx] = val
            stack.append(i)

        return res

