from collections import deque

class Solution:
    def max_sliding_window(self, nums: list[int], k: int) -> list[int]:
        res = []
        q = deque()

        for i, val in enumerate(nums):
            while q and q[0] < i - k + 1:
                q.popleft()

            while q and nums[q[-1]] < val:
                q.pop()

            q.append(i)

            if i >= k - 1:
                res.append(nums[q[0]])

        return res

