class Solution:
    def find_min_arrows(self, points: list[list[int]]) -> int:
        if not points: return 0

        points.sort(key=lambda x: x[1])
        arrows = 1
        current_end = points[0][1]

        for start, end in points[1:]:
            if start > current_end:
                arrows += 1
                current_end = end

        return arrows

